import * as React from 'react';
import {
  DataGridPremium,
  GridColDef,
  GridPastedValueParser,
} from '@mui/x-data-grid-premium';

const numberPastedValueParser: GridPastedValueParser = (value, _, column) => {
  if (column.type === 'number' && Number.isNaN(Number(value))) {
    return undefined;
  }
  return value;
};

const columns: GridColDef[] = [
  {
    field: 'product',
    headerName: 'Product',
    width: 150,
    editable: true,
    rowHeader: true,
  },
  {
    field: 'region',
    headerName: 'Region',
    width: 120,
    editable: true,
  },
  {
    field: 'q1',
    headerName: 'Q1',
    type: 'number',
    pastedValueParser: numberPastedValueParser,
    width: 100,
    editable: true,
  },
  {
    field: 'q2',
